from html import escape
import json,re

def refine(g):
 pages=g['pages'];config=g['config'];intro=g['intro'];faq=g['faq'];P=g['P']
 endpoint=config['formEndpoint']; booking=config['bookingUrl'];email=config['email']
 g['nav']='<a href="/work/">Work</a><a href="/services/">Services</a><a href="/about/">About</a><a href="/contact/">Contact</a>'
 (P/'site-config.js').write_text('window.SITESUTRA_CONFIG='+json.dumps({k:config[k] for k in ['formEndpoint','bookingUrl','bookingTimezone','email']})+';')
 def brief():
  book=f'<a class="textlink booking" href="{escape(booking)}">Book a discovery call ↗</a><p class="fine">Choose a time in your timezone on the booking page. Founder timezone: Asia/Kolkata.</p>' if booking else '<p class="fine">Prefer a call? Email your timezone and a few suitable times. Kumar works from India (Asia/Kolkata).</p>'
  return f'''<section class="contactsection"><div><span class="eyebrow">YOUR PROJECT / FIRST CONVERSATION</span><h2>A clear brief.<br>A useful next step.</h2><p>Share what your business needs. Kumar will review your goals, clarify the scope, and discuss a tailored quote.</p><a class="email" href="mailto:{email}">{email} ↗</a>{book}<p class="fine">Varanasi, India · Direct founder involvement</p></div><form id="enquiry" {'action="'+escape(endpoint)+'" method="post"' if endpoint else ''} aria-describedby="form-note"><div class="formrow"><label>Your name<input required maxlength="120" name="name" autocomplete="name"></label><label>Email address<input required maxlength="254" type="email" name="email" autocomplete="email"></label></div><label>Service<select required name="service"><option value="">Select a service</option><option>Website design & development</option><option>Branding & design</option><option>SEO & digital marketing</option><option>Agency partnership</option></select></label><label>Existing website (optional)<input type="url" name="website" placeholder="https://" maxlength="500"></label><label>What should this project achieve?<textarea required minlength="10" maxlength="5000" name="goal" rows="3" placeholder="Your audience, current challenge, and desired outcome"></textarea></label><div class="formrow"><label>Budget (optional)<input name="budget" maxlength="100" placeholder="Amount and currency, or open to advice"></label><label>Timeline<select required name="timeline"><option value="">Choose a timeframe</option><option>Within 1 month</option><option>1–3 months</option><option>3–6 months</option><option>Flexible / exploring</option></select></label></div><div class="honeypot" aria-hidden="true"><label>Leave blank<input name="_gotcha" tabindex="-1" autocomplete="off"></label></div><button class="btn orange" type="submit">Send project brief <span>↗</span></button><p id="form-note" class="fine">{'Your brief is sent to the configured enquiry provider. See our privacy information.' if endpoint else 'Preview: submission delivery is not connected yet. Please use direct email; this form cannot send your brief.'} <a href="/privacy/">Privacy</a></p><p id="formstatus" role="status" aria-live="polite" tabindex="-1"></p><noscript><p class="fine">{'You can submit this form using the provider’s standard confirmation page.' if endpoint else 'Please email Kumar directly to enquire.'}</p></noscript></form></section>'''
 oldcontact=g['contact']()
 for r,(t,b) in list(pages.items()):
  b=b.replace(oldcontact,brief()).replace('Pricing: [to be confirmed].','Request a tailored quote.').replace('Project fee: [editable pricing placeholder].','Request a tailored quote.').replace('a fixed fee [pricing to be confirmed]','a fixed fee. Request a tailored quote')
  pages[r]=(t,b)
 def thumb(kind):
  if kind=='olive':return '''<div class="projectvisual olivevisual"><div class="mininav">OLIVE & EARTH <span>Objects / Materials / Story</span></div><div class="olivethumb"><div><small>FEWER, BETTER OBJECTS</small><h3>Everyday rituals.<br>Considered objects.</h3><span>Shop ceramics ↗</span></div><div class="vesselart" aria-label="Original ceramic vessel illustration" role="img"><i class="vase"></i><i class="bowl"></i></div></div><div class="visualfoot">Ceramics &nbsp; Textiles &nbsp; Living</div></div>'''
  return '''<div class="projectvisual archvisual"><div class="mininav">FORM / SPACE <span>Projects / Approach / Studio</span></div><img src="/assets/courtyard.svg" alt="Concept illustration of a courtyard house with afternoon shadows"><div class="archtitle"><h3>Architecture for<br>the way we live.</h3><small>COURTYARD HOUSE / JAIPUR · FICTIONAL BRIEF</small></div></div>'''
 def work():
  return '<div class="projects">'+''.join(f'<a class="project" href="/work/{s}/">{thumb(k)}<div class="projectcaption"><div><small>{tag} · Concept</small><h3>{n}</h3><p>{d}</p></div><span class="circle">↗</span></div></a>' for s,n,d,k,tag in g['projects'])+'</div>'
 oldwork=g['work']()
 for r,(t,b) in list(pages.items()):pages[r]=(t,b.replace(oldwork,work()))
 pages['/work/']=('Website concept case studies',intro('WORK / ORIGINAL CONCEPTS','Different businesses.<br>Different journeys.','A retail experience built around materials and everyday rituals. An architecture studio built around places and project stories. Explore the working demonstrations and the decisions behind them.')+'<section class="workgallery">'+work()+'</section>'+brief())
 overview='<section><div class="servicegrid">'+''.join(f'<a class="servicecard" href="/services/{s}/"><small>0{i+1}</small><h3>{n}</h3><p>{b}</p><span>Deliverables & approach ↗</span></a>' for i,(s,n,t,b,d) in enumerate(g['services']))+'<a class="servicecard navy" href="/agency-partnerships/"><small>04</small><h3>Agency partnerships</h3><p>White-label website and design delivery. Agree client boundaries, handover, revision rounds and support through a fixed-scope paid pilot.</p><span>Explore partnership delivery ↗</span></a></div></section>'
 pages['/services/']=('Website, design, SEO & agency services',intro('SERVICES','Start with the website.<br>Connect the rest.','Plan your pages, design a clear customer journey, build a responsive site, and make it easier for the right people to find you. Add brand design and marketing where they help your next goal.')+overview+'<section class="reading"><h2>Request a tailored quote.</h2><p>Each proposal sets out deliverables, responsibilities, milestones, revision rounds, and a project fee. Hosting, licences, ongoing support, and advertising budgets are agreed separately.</p></section>'+brief())
 pages['/about/']=('Kumar Saurabh Mishra — founder, Varanasi',intro('ABOUT / KUMAR SAURABH MISHRA','A connected practice.<br>A personal commitment.','Founder of SiteSutra. Based in Varanasi, India. 10+ years of experience, with skills across website development, design, SEO, and digital marketing.')+'''<section class="founder aboutfounder"><div class="founderart"><span>VARANASI, INDIA</span><div>k<span>↗</span></div><small>KUMAR SAURABH MISHRA / FOUNDER</small></div><div><h2>Why SiteSutra?</h2><p>I started SiteSutra to bring my skills together in a founder-led studio. A business website connects many things: what you offer, how you look, how people find you, and how they get in touch. I want to make those parts work together.</p><p>My focus is website projects for overseas businesses and delivery partnerships with agencies. You work directly with me, from the first conversation through design, build, and handover.</p></div></section><section class="reading"><h2>How we’ll work together</h2><h3>Clear scope before creation</h3><p>We identify your audience, agree the pages and deliverables, and document approval points. A tailored quote gives you a clear basis for the decision.</p><h3>Communication across timezones</h3><p>We agree an overlap window, review cadence, and communication channel at the start. My working timezone is Asia/Kolkata.</p><h3>A useful handover</h3><p>You receive agreed editable files, documentation, and guidance. Ownership and support responsibilities are written into the scope.</p></section>'''+(''.join(f'<a class="textlink" href="{escape(x["url"])}">{escape(x["label"])}</a>' for x in config['profileLinks']))+brief())
 # Homepage: replace the three preview panels as a group.
 panels='''<div id="panel-design" role="tabpanel" aria-labelledby="tab-design" tabindex="0"><div class="designboard">'''+thumb('olive')+'''<ol class="annotations"><li><b>01 / Hierarchy</b> One offer, a short headline, and a clear shopping entry.</li><li><b>02 / Palette</b> Olive, clay, and cream echo the materials.</li><li><b>03 / Type</b> Editorial serif headings paired with practical sans-serif details.</li></ol><div class="swatches"><span style="--swatch:#363e31">Olive</span><span style="--swatch:#ba6a47">Clay</span><span style="--swatch:#ebe9d9">Cream</span></div></div></div><div id="panel-build" role="tabpanel" aria-labelledby="tab-build" tabindex="0" hidden><div class="devicebuttons" aria-label="Build preview size"><button type="button" data-device="desktop" aria-pressed="true">Desktop</button><button type="button" data-device="mobile" aria-pressed="false">Mobile</button></div><div class="buildpreview" data-device-preview>'''+thumb('olive')+'''</div><details class="component"><summary>Try a product-information component <span>+</span></summary><p>Clay vessel · Hand-finished stoneware concept. A useful detail beside the buying decision.</p></details><a class="textlink" href="/demos/olive-earth/">Open working retail demo ↗</a></div><div id="panel-grow" role="tabpanel" aria-labelledby="tab-grow" tabindex="0" hidden><div class="grow growthboard"><small>ILLUSTRATIVE ENQUIRY JOURNEY</small><h3>From a useful answer<br>to a useful conversation.</h3><ol class="journeymap"><li>Buyer guide<span>Page visit</span></li><li>Relevant case study<span>Demo exploration</span></li><li>Project brief<span>Submission accepted</span></li><li>Discovery conversation<span>Qualified enquiry</span></li></ol><p><b>Content plan:</b> service explanations → scope guide → original case study.</p><p><b>Measurement plan:</b> record consented page visits and accepted enquiries, then review enquiry quality. No analytics or results are claimed.</p></div></div>'''
 t,b=pages['/'];start=b.index('<div id="panel-design"');end=b.index('<p class="demolabel">',start);b=b[:start]+panels+b[end:]
 b=b.replace('Websites, design, and search marketing.<br>Thoughtfully connected. Delivered directly by the founder.','Custom websites with clear content, responsive design, and search foundations. Work directly with Kumar, from the first brief through launch.').replace('ORIGINAL CONCEPT DEMONSTRATION · NOT CLIENT WORK','OLIVE & EARTH / ORIGINAL CONCEPT').replace('A glimpse of the thinking and craft.<br>Original concepts, clearly labelled.','Explore retail and architecture journeys.<br>See the working demos and design decisions.')
 b=b.replace('<section class="proof">'+b.split('<section class="proof">')[1].split('</section>')[0]+'</section>','<section class="proof"><span class="eyebrow">DECISIONS YOU CAN SEE</span><h3>Explore the work. Understand the thinking.</h3><p>Each original concept includes a working demo, design decisions, and a clear account of its scope.</p><a class="textlink" href="/work/">Explore the case studies ↗</a></section>')
 b=b.replace('I’m Kumar Saurabh Mishra, the founder of SiteSutra. Based in India,','I’m Kumar Saurabh Mishra, the founder of SiteSutra. Based in Varanasi, India, with 10+ years of experience,')
 pages['/']=(t,b)
 # Rich case studies include full demo routes, responsive iframes and a functioning comparison.
 for slug,name,desc,k,tag in g['projects']:
  olive=k=='olive'; demo='/demos/'+slug+'/'
  decisions=[('Lead with a shopping task','Categories and product details turn a brand impression into a clear route to an object.'),('Let materials explain the value','Material and care information appear beside product choices, with prices explicitly marked as illustrative.'),('Keep the basket understandable','Add, remove, and empty states are visible. Status updates announce basket changes without moving focus.')] if olive else [('Let the building lead','Large original concept illustrations and concise project titles put the practice’s work first.'),('Show the thinking behind a place','Each project connects a fictional location, spatial intention, and material direction.'),('Make consultation a separate decision','Project exploration leads to a consultation brief, with a clearly labelled local-only demonstration state.')]
  annotations='<div class="decisiongrid">'+''.join(f'<article><small>0{i+1}</small><h3>{a}</h3><p>{d}</p></article>' for i,(a,d) in enumerate(decisions))+'</div>'
  before='A generic headline and one broad shopping button hide the product categories.' if olive else 'Generic navigation and vague service language fail to explain the architecture practice.'
  after='Material-led product details, category filters, and a visible demonstration basket.' if olive else 'Project-led navigation, fictional locations, an approach statement, and a consultation brief.'
  body=intro('CASE STUDY / ORIGINAL CONCEPT',name,desc)+f'<section class="casetop">{thumb(k)}<div class="actions"><a class="btn" href="{demo}">Explore live demo ↗</a><a class="textlink" href="/contact/">Discuss a similar project ↗</a></div></section>'
  body+='<section class="casebrief"><div><span class="eyebrow">BRIEF & AUDIENCE</span><h2>'+('Objects with a story.<br>A shop with a purpose.' if olive else 'Spaces with intention.<br>A practice with a point of view.')+'</h2><p>'+('Create a lifestyle retail concept for people choosing considered home objects. Help them browse by category, understand materials, inspect a product, and use a simple basket.' if olive else 'Create an architecture-studio concept for prospective residential clients. Help them explore project intentions, understand the studio approach, and prepare a consultation brief.')+'</p></div><div><span class="eyebrow">MY ROLE & SCOPE</span><p>Original brief, art direction, interface design, content structure, responsive development, and interaction design.</p><p>'+('Product artwork is created in CSS. The catalogue and prices are illustrative.' if olive else 'Architectural images are original vector concept illustrations. Buildings and project locations are fictional design briefs.')+'</p></div></section>'
  body+='<section><span class="eyebrow">THREE DESIGN DECISIONS</span><h2>The reasoning behind the interface.</h2>'+annotations+'</section>'
  body+=f'''<section class="previewsection"><span class="eyebrow">DESKTOP & MOBILE / FULL WORKING PREVIEWS</span><h2>Explore both perspectives.</h2><p>These embedded demos are interactive. Each contains its complete page; scroll within a preview, or open the demo directly.</p><div class="previewpair"><div><h3>Desktop</h3><iframe title="{name} desktop demonstration" src="{demo}" loading="lazy" class="desktopframe"></iframe></div><div><h3>Mobile</h3><iframe title="{name} mobile demonstration" src="{demo}" loading="lazy" class="mobileframe"></iframe></div></div></section>'''
  body+=f'<section class="fullcaptures"><h2>Full-page design previews</h2><div class="capturegrid"><a href="/assets/{slug}-desktop.png"><img loading="lazy" src="/assets/{slug}-desktop.png" alt="Complete {name} desktop design"><span>Open full desktop capture ↗</span></a><a href="/assets/{slug}-mobile.png"><img loading="lazy" src="/assets/{slug}-mobile.png" alt="Complete {name} mobile design"><span>Open full mobile capture ↗</span></a></div></section>'
  body+=f'''<section class="comparison"><span class="eyebrow">ANNOTATED REDESIGN / ORIGINAL DEMONSTRATION</span><h2>A clearer route through the page.</h2><div class="comparecontrols"><button type="button" data-compare="before" aria-pressed="true">Before / generic approach</button><button type="button" data-compare="after" aria-pressed="false">After / considered direction</button></div><div data-comparison="before"><h3>{'Everything for your home.' if olive else 'Welcome to our studio.'}</h3><p>{before}</p><span class="comparisonannotation">↳ One vague entry point. Missing decision-making information.</span></div><div data-comparison="after" hidden>{thumb(k)}<p>{after}</p><span class="comparisonannotation">↳ Specific content and navigation follow the visitor’s task.</span></div></section>'''
  body+='<section class="reading"><h2>Content structure & accessibility</h2><p>'+('Category browsing → product details → materials and care → basket review.' if olive else 'Selected projects → location and project story → studio philosophy → consultation brief.')+' Semantic navigation, visible keyboard focus, labelled controls, text alternatives for concept imagery, and announced interaction states keep the route understandable. Layouts stack naturally on mobile, with no motion required to access content.</p><h2>Demonstration boundaries</h2><p>'+('This fictional catalogue supports local basket interactions only. No payments, orders, inventory, or customer records are created.' if olive else 'These fictional projects do not represent completed buildings or commissioned work. The consultation form is a local demonstration and does not send enquiries.')+' No commercial results or client endorsements are claimed.</p><a class="btn" href="/contact/">Discuss a similar project ↗</a></section>'+brief()
  pages['/work/'+slug+'/']=(name+' — interactive concept case study',body)
 # Buyer guides: useful, specific source content, no fabricated prices.
 guides=[('scope','What belongs in a website scope?','Agree the decisions before the design.','A scope should describe what will be delivered and how you will know it is ready.',[('Pages and content','List the page types, approximate content volume, and who writes, supplies, and approves each item. A five-page brochure and a catalogue with hundreds of products are different projects.'),('Functions and integrations','Describe each visitor task: enquire, book, buy, search, or download. Name the systems it depends on and assign responsibility for accounts and access.'),('Acceptance and ownership','Agree device and browser checks, revision rounds, launch responsibilities, editable files, and ownership. Record exclusions as carefully as inclusions.')]),('costs','What affects a website quote?','Price starts with scope.','A useful quote separates the project from the services that continue after launch.',[('Project fees','Page complexity, original design, content work, integrations, migration and testing all affect effort. Request a tailored quote with explicit deliverables rather than comparing headline prices alone.'),('Recurring costs','Hosting, domains, software licences and maintenance may recur. Ask who pays, what renews, and who owns the accounts. Advertising spend is separate from website and campaign-management fees.'),('Changes and support','Agree how additional work is priced and what launch support covers. Keep optional maintenance separate so you can compare proposals fairly.')]),('platforms','How should you choose a website platform?','Start with what you need to edit.','A platform decision should follow your content, transactions, and maintenance capacity.',[('Simple information sites','A static site can suit a small, stable set of pages. It has fewer moving parts, but editing may require a straightforward source workflow or an added content editor.'),('Regular publishing','If several people publish frequently, evaluate editing roles, previews, revisions, and portability. Ask for a demonstration of the exact publishing tasks you need.'),('Selling and integrations','For commerce, consider product management, payment requirements, shipping, taxes, and third-party systems. Confirm availability and fees directly with the chosen provider before committing.')]),('redesign','When does a website need a redesign?','Find the friction before changing the look.','A redesign brief is stronger when it identifies the decisions visitors struggle to make.',[('Review the customer journey','Can a first-time visitor explain the offer, see relevant proof, and find the next step? Check mobile reading, broken links, slow pages, and enquiry friction.'),('Keep useful foundations','Inventory existing content, URLs, search visibility and integrations. Plan redirects where URLs change and preserve content that still serves buyers.'),('Define a meaningful outcome','Pick specific improvements: clearer services, stronger case studies, easier content editing, or a working enquiry route. Use verified observations to evaluate the result, without assuming design alone will create growth.')])]
  # end guides list
 pages['/guides/']=('Website buyer guides',intro('BUYER GUIDES','Make the next decision<br>with more clarity.','Practical questions to bring to your website project: scope, cost, platform, and whether a redesign is the right next step.')+'<section class="guidegrid">'+''.join(f'<a class="guidecard" href="/guides/{s}/"><small>PLANNING / {i+1:02}</small><h2>{title}</h2><p>{desc}</p><span>Read guide ↗</span></a>' for i,(s,title,headline,desc,sections) in enumerate(guides))+'</section>'+brief())
 for s,title,headline,desc,sections in guides:
  pages['/guides/'+s+'/']=(title,intro('BUYER GUIDE / BY KUMAR SAURABH MISHRA',headline,desc)+'<section class="reading">'+''.join(f'<h2>{h}</h2><p>{b}</p>' for h,b in sections)+'<p><a class="textlink" href="/guides/">← All buyer guides</a></p><a class="btn" href="/contact/">Discuss your website scope ↗</a></section>')
 pages['/privacy/']=('Privacy information',intro('PRIVACY','Your information.<br>A clear purpose.','Updated 14 October 2026.')+'<section class="reading"><h2>Project enquiries</h2><p>'+('The project brief is submitted to the configured form provider to notify Kumar Saurabh Mishra. It includes your name, email, chosen service, website, goal, budget if entered, and timeline.' if endpoint else 'Project-brief delivery is not configured in this preview. The form does not transmit or save your entries. You can enquire directly by email.')+'</p><p>Emails sent to contactkumarsmishra@gmail.com are received by Kumar and processed by the relevant email providers. Information is used to respond and discuss the project; sending an enquiry does not subscribe you to marketing.</p><h2>Your requests</h2><p>Contact Kumar to ask about access, correction or deletion of enquiry information. Any retention arrangements will be confirmed for the configured submission service before launch.</p><h2>Concept interactions</h2><p>Demonstration baskets and consultation previews run in the current page only. They do not create orders, appointments, payments, or customer records.</p><h2>Hosting and fonts</h2><p>Hosting providers may process request information for delivery and security. Typography is loaded through Google Fonts, which receives browser requests. No analytics or advertising trackers are implemented by this site. Private hosting access controls may use essential authentication mechanisms.</p><h2>Contact</h2><p>Kumar Saurabh Mishra · Varanasi, India<br><a href="mailto:'+email+'">'+email+'</a></p></section>')
 g['descriptions']={r:re.sub('<[^>]*>','',t)+' — '+('Original working concept and annotated design case study by SiteSutra.' if r.startswith('/work/') else 'Founder-led website design, development and digital services from Varanasi, India.') for r,(t,b) in pages.items()}
